versions.variantCss:
.wemd-section-divider[data-variant="bytedance-divider-wave"] {
  margin: 40px 0;
  padding: 24px 0;
  text-align: center;
  border-top: 1px solid var(--wemd-border-soft);
  border-bottom: 1px solid var(--wemd-border-soft);
}
.wemd-section-divider[data-variant="bytedance-divider-wave"] .wemd-sd-part {
  color: var(--wemd-primary);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 4px;
  text-transform: uppercase;
  margin: 0 0 8px 0;
}
.wemd-section-divider[data-variant="bytedance-divider-wave"] .wemd-sd-title {
  color: var(--wemd-text-strong);
  font-size: 22px;
  font-weight: 700;
  margin: 0;
}
